/* xx_lzk00_extractor.c - search raw data for LZK00.
 *
 * Scans for:
 *   4C 5A 4B 30 30 00 00 00 00 at +0  ("LZK00....")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the lzk00 reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/lzk00/xx_lzk00.h"

static const uint8_t k_anchor0[] = { 0x4C, 0x5A, 0x4B, 0x30, 0x30, 0x00, 0x00, 0x00, 0x00 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_LZK00 };

static Abstractformat *xx_lzk00_search_open(xx_io_device *window) {
    xx_lzk00 *reader = xx_lzk00_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_lzk00_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_lzk00_free((xx_lzk00 *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_lzk00_search_open, xx_lzk00_search_close
};

static xx_format_search_state *xx_lzk00_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_lzk00_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_lzk00_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_lzk00_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_lzk00_extractor = {
    xx_lzk00_create_format_search,
    xx_lzk00_get_current_format_info,
    xx_lzk00_format_search_find_next,
    xx_lzk00_free_format_search
};
